        var view=editor(owner);if(view==null)return;var actor=Actor(owner);var model=Model(owner);string actorId=actor.Get("id").AsString();var state=Get(view.Get("physics").AsGodotObject().Get("display_states").AsGodotDictionary(),actorId,new Settings()).AsGodotDictionary();var fragments=Get(state,"destruction_fragments",new GArray()).AsGodotArray();if(fragments.Count==0){Status(owner).Text="Scrub past a fracture first, then select the resulting pieces.";return;}var dialog=new AcceptDialog{Title="Fragment direction & animation corrections",Name="FragmentDirector"};owner.AddChild(dialog);var fields=new VBoxContainer();dialog.AddChild(fields);var mode=new OptionButton();mode.AddItem("Simulation guidance — recalculates physics");mode.AddItem("Animation-only corrections — preserves bake");fields.AddChild(mode);var list=new ItemList{Name="FragmentList",SelectMode=ItemList.SelectModeEnum.Multi,CustomMinimumSize=new Vector2(420,110)};fields.AddChild(list);var ids=new GArray();var previously=actor.GetMeta("damage_selected_fragments",new GArray()).AsGodotArray();for(int i=0;i<fragments.Count;i++){var fragment=fragments[i].AsGodotDictionary();string key=_authoring.fragment_key(actorId,fragment["id"].AsString());ids.Add(key);list.AddItem("Piece "+(i+1)+" · "+fragment["mass"].AsDouble().ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" kg");list.SetItemMetadata(i,key);if(previously.Contains(key))list.Select(i,false);}if(list.GetSelectedItems().Length==0){list.Select(0);actor.SetMeta("damage_selected_fragments",new GArray{ids[0]});}GArray SelectedIds(){var chosen=new GArray();foreach(int index in list.GetSelectedItems())chosen.Add(ids[index]);actor.SetMeta("damage_selected_fragments",chosen);return chosen;}list.MultiSelected+=(_,_)=>SelectedIds();var options=new VBoxContainer();fields.AddChild(options);
        void Rebuild()
