gment_"+key+"_"+axis;input.Step=.01;input.AllowGreater=true;input.AllowLesser=true;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;row.AddChild(input);input.SetValueNoSignal(vector?initial.AsVector3()[axis]:initial.AsDouble());Variant Convert(double value){if(!vector)return value;var current=SelectedIds();var next=current.Count>0?_animation.sampled_value(actor,new[]{field.ToString(),current[0].AsString(),key},actor.Get("animation_time").AsDouble(),initial).AsVector3():initial.AsVector3();next[component]=(float)value;return next;}input.ValueChanged+=value=>_authoring.edit_fragments(model,actor,field,SelectedIds(),key,Convert(value));input.Connect("drag_committed",Callable.From<double>(value=>_authoring.edit_fragments(model,actor,field,SelectedIds(),key,Convert(value))));}}options.AddChild(new Label{Text=mode.Selected==1?"Offsets are visual animation overrides; they do not recalculate collisions.":"Targets use world coordinates. Release retains the last animated velocity.",AutowrapMode=TextServer.AutowrapMode.WordSmart});
        }
        mode.ItemSelected+=_=>Rebuild();list.MultiSelected+=(_,_)=>Rebuild();Rebuild();dialog.Confirmed+=dialog.QueueFree;dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(640,640));
